#!/bin/bash
# 31_music_search_result.sh v2
set -e
cd "$(dirname "$0")/../.." 2>/dev/null || true
BASE="avbox"
TARGET="$BASE/app/src/main/java/com/github/tvbox/osc/ui/music/search/SearchResultScreen.kt"

if [ -f "$TARGET" ] && grep -q "fun SearchResultScreen(" "$TARGET" 2>/dev/null; then
  echo "跳过（SearchResultScreen.kt 已写入）"
else
  mkdir -p "$(dirname "$TARGET")"
  echo "" | base64 -d > "$TARGET"
  echo "已写入 search/SearchResultScreen.kt"
fi

python3 << 'PYEOF'

import re, sys
TARGET = "avbox/app/src/main/java/com/github/tvbox/osc/ui/activity/LxMusicSearchActivity.kt"
src = open(TARGET, encoding='utf-8').read()

MARK = "// SEARCH_WIRE_V2"
if MARK in src:
    print("跳过（SEARCH_WIRE_V2 已存在）")
    sys.exit(0)

if "ui.music.search.SearchResultScreen" not in src:
    src = src.replace(
        "package com.github.tvbox.osc.ui.activity",
        "package com.github.tvbox.osc.ui.activity\n\nimport com.github.tvbox.osc.ui.music.search.SearchArtist\nimport com.github.tvbox.osc.ui.music.search.SearchAlbum\nimport com.github.tvbox.osc.ui.music.search.SearchResultScreen\nimport com.github.tvbox.osc.ui.music.search.SearchResultSong",
        1
    )

box_anchor = "    Box(\n        modifier = Modifier\n            .fillMaxSize()\n            .background(SearchBg)"
box_idx = src.find(box_anchor)
if box_idx < 0:
    print("失败：找不到 Box 锚点", file=sys.stderr); sys.exit(1)

dlg_idx = src.find("if (selectedAlbumSongs != null) {", box_idx)
if dlg_idx < 0:
    print("失败：找不到 Dialog 锚点", file=sys.stderr); sys.exit(1)

new_ui = '''    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(MaterialTheme.colorScheme.background)
    ) {
        // SEARCH_WIRE_V2: 搜索结果新版 UI；数据逻辑保持不动
        SearchResultScreen(
            query = keyword,
            onQueryChange = { keyword = it },
            onSearch = { doSearch() },
            onClearQuery = { keyword = "" },
            onBack = onBack,
            artist = artistResult?.let { SearchArtist(name = it.name, avatarUrl = it.picUrl) },
            onArtistClick = {
                artistResult?.let { artist ->
                    val intent = Intent(context, LxArtistDetailActivity::class.java).apply {
                        putExtra("platform", artist.platform)
                        putExtra("artistId", artist.id)
                        putExtra("artistName", artist.name)
                        putExtra("picUrl", artist.picUrl)
                    }
                    context.startActivity(intent)
                }
            },
            albums = albumResults.map { SearchAlbum(name = it.name, artist = it.artist, coverUrl = it.picUrl) },
            onAlbumClick = { album ->
                albumResults.find { it.name == album.name }?.let {
                    selectedAlbumName = it.name
                    isLoadingAlbumSongs = true
                    selectedAlbumSongs = emptyList()
                    scope.launch {
                        try {
                            selectedAlbumSongs = LxMusicSearchApi.getAlbumSongs(it.platform.ifEmpty { "wy" }, it.id, it.name)
                        } catch (e: Exception) {
                            selectedAlbumSongs = emptyList()
                        } finally {
                            isLoadingAlbumSongs = false
                        }
                    }
                }
            },
            songs = results.map {
                SearchResultSong(id = it.id, platform = it.platform, title = it.title, artist = it.artist, album = it.album, coverUrl = it.picUrl, durationSec = it.duration, qualityLabel = it.quality)
            },
            onSongClick = { s ->
                val song = results.find { it.id == s.id && it.platform == s.platform }
                    ?: fullResults.firstOrNull { it.id == s.id && it.platform == s.platform }
                song?.let {
                    val realSong = fullResults.firstOrNull { r -> r.id == it.id && r.platform == it.platform } ?: it
                    onPlay(realSong, fullResults)
                }
            },
        )
'''

src = src[:box_idx] + new_ui + src[dlg_idx:]

if src.count('{') != src.count('}'):
    print("失败：括号不平衡", file=sys.stderr); sys.exit(1)

open(TARGET, 'w', encoding='utf-8').write(src)
print("接线成功")

PYEOF
echo "31 完成"
